package com.devdesk.agent;

import java.util.regex.Pattern;
import java.util.Locale;

/** Public chat API accepts canonical UUID keys, generated by the client or evaluator. */
public final class IdempotencyKey {

    private static final Pattern UUID_KEY = Pattern.compile(
            "(?i)^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$");

    private IdempotencyKey() {}

    public static boolean isValid(String key) {
        return key != null && UUID_KEY.matcher(key).matches();
    }

    public static String canonical(String key) {
        if (!isValid(key)) throw new IllegalArgumentException("A canonical UUID idempotency key is required.");
        return key.toLowerCase(Locale.ROOT);
    }
}
